-- ENGENDRÉ PAR `rake monoschema:schema` — NE PAS MODIFIER À LA MAIN.
--
-- Forme d'arrivée du mono-schéma : toutes les tables du plan de données
-- portent `tenant_id`, une clé primaire composite et la Row Level
-- Security ; le référentiel vit dans `lexicon`, le plan de contrôle et les
-- données dans `ekylibre`, les extensions dans `postgis`.
--
-- Ce fichier ne migre rien : il montre où l'on va. Les migrations de
-- données — fusion des schémas par ferme, renumérotation des clés,
-- déduplication des cinq tables qui passent au référentiel — viennent
-- après, et sur cette cible.

CREATE SCHEMA IF NOT EXISTS ekylibre;
CREATE SCHEMA IF NOT EXISTS lexicon;
CREATE EXTENSION IF NOT EXISTS btree_gist;
SET search_path TO ekylibre, lexicon, public, postgis;

-- Plan de contrôle minimal : le point 1.14 lui ajoutera `users` et
-- `user_tenants`.
CREATE TABLE ekylibre.tenants (
    id uuid DEFAULT uuidv7() NOT NULL,
    slug character varying NOT NULL,
    created_at timestamp(6) without time zone DEFAULT now() NOT NULL,
    updated_at timestamp(6) without time zone DEFAULT now() NOT NULL,
    CONSTRAINT tenants_pkey PRIMARY KEY (id),
    CONSTRAINT tenants_slug_key UNIQUE (slug)
);

-- Le plan de contrôle du chemin inter-fermes (point 1.22). Une ferme
-- n'entre dans l'agrégation d'une autre que si elle y figure.
CREATE TABLE ekylibre.tenant_shares (
    id uuid DEFAULT uuidv7() NOT NULL,
    consumer_tenant_id uuid NOT NULL REFERENCES ekylibre.tenants (id),
    shared_tenant_id uuid NOT NULL REFERENCES ekylibre.tenants (id),
    purpose character varying NOT NULL,
    created_at timestamp(6) without time zone DEFAULT now() NOT NULL,
    CONSTRAINT tenant_shares_pkey PRIMARY KEY (id),
    CONSTRAINT tenant_shares_unicity UNIQUE (consumer_tenant_id, shared_tenant_id, purpose)
);

-- Les fermes lisibles : la ferme courante, plus celles que le chemin
-- inter-fermes demande *et* que le plan de contrôle autorise.
-- L'application ne peut donc pas s'ouvrir une ferme qui n'a pas
-- consenti, même en posant le réglage elle-même.
--
-- Une seule fonction, qui rend un tableau : la politique s'écrit alors
-- `tenant_id = ANY (…)`, une condition que le planificateur sait porter
-- sur un index. Écrite en `OR` — ferme courante OU fermes partagées —
-- elle produisait un `BitmapOr` qui rejetait le prédicat spatial en
-- filtre : 1 920 lignes écartées après coup au lieu d'un parcours GiST.
-- Mesuré, puis corrigé.
CREATE FUNCTION ekylibre.readable_tenants() RETURNS uuid[]
LANGUAGE sql STABLE AS $$
  SELECT COALESCE(ARRAY(
    SELECT NULLIF(current_setting('app.tenant_id', true), '')::uuid
     WHERE NULLIF(current_setting('app.tenant_id', true), '') IS NOT NULL
    UNION
    SELECT s.shared_tenant_id
      FROM ekylibre.tenant_shares s
     WHERE s.consumer_tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid
       AND s.shared_tenant_id = ANY (
         COALESCE(string_to_array(NULLIF(current_setting('app.tenant_ids', true), ''), ',')::uuid[],
                  ARRAY[]::uuid[])
       )
  ), ARRAY[]::uuid[])
$$;

