    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    wine_incoming_harvest_id bigint NOT NULL,
    input_id uuid NOT NULL,
    quantity_value numeric(19,4) NOT NULL,
    quantity_unit character varying NOT NULL,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    creator_id bigint,
    updater_id bigint,
    lock_version integer DEFAULT 0 NOT NULL,
    CONSTRAINT wine_incoming_harvest_inputs_pkey PRIMARY KEY (tenant_id, id)
);

CREATE TABLE ekylibre.wine_incoming_harvest_plants (
    tenant_id uuid NOT NULL,
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    wine_incoming_harvest_id bigint NOT NULL,
    plant_id uuid NOT NULL,
    harvest_percentage_received numeric(19,4) CONSTRAINT wine_incoming_harvest_plant_harvest_percentage_receive_not_null NOT NULL,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    creator_id bigint,
    updater_id bigint,
    lock_version integer DEFAULT 0 NOT NULL,
    rows_harvested character varying,
    CONSTRAINT wine_incoming_harvest_plants_pkey PRIMARY KEY (tenant_id, id)
);

CREATE TABLE ekylibre.wine_incoming_harvest_presses (
    tenant_id uuid NOT NULL,
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    wine_incoming_harvest_id bigint NOT NULL,
    press_id uuid,
    quantity_value numeric(19,4) NOT NULL,
    quantity_unit character varying NOT NULL,
    pressing_started_at time without time zone,
    pressing_schedule character varying,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    creator_id bigint,
    updater_id bigint,
    lock_version integer DEFAULT 0 NOT NULL,
    CONSTRAINT wine_incoming_harvest_presses_pkey PRIMARY KEY (tenant_id, id)
);

CREATE TABLE ekylibre.wine_incoming_harvest_storages (
    tenant_id uuid NOT NULL,
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    wine_incoming_harvest_id bigint CONSTRAINT wine_incoming_harvest_storage_wine_incoming_harvest_id_not_null NOT NULL,
    storage_id uuid NOT NULL,
    quantity_value numeric(19,4) NOT NULL,
    quantity_unit character varying NOT NULL,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    creator_id bigint,
    updater_id bigint,
    lock_version integer DEFAULT 0 NOT NULL,
    CONSTRAINT wine_incoming_harvest_storages_pkey PRIMARY KEY (tenant_id, id)
);

CREATE TABLE ekylibre.wine_incoming_harvests (
    tenant_id uuid NOT NULL,
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    number character varying,
    ticket_number character varying,
    description text,
    campaign_id bigint NOT NULL,
    analysis_id uuid,
    received_at timestamp without time zone NOT NULL,
    quantity_value numeric(19,4) NOT NULL,
    quantity_unit character varying NOT NULL,
    additional_informations jsonb DEFAULT '{}'::jsonb,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    creator_id bigint,
    updater_id bigint,
    lock_version integer DEFAULT 0 NOT NULL,
    CONSTRAINT wine_incoming_harvests_pkey PRIMARY KEY (tenant_id, id)
);

CREATE TABLE ekylibre.worker_contract_distributions (
    tenant_id uuid NOT NULL,
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    worker_contract_id bigint NOT NULL,
    affectation_percentage numeric(19,4) NOT NULL,
    main_activity_id bigint NOT NULL,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    creator_id bigint,
    updater_id bigint,
    lock_version integer DEFAULT 0 NOT NULL,
    CONSTRAINT worker_contract_distributions_pkey PRIMARY KEY (tenant_id, id)
);

CREATE TABLE ekylibre.worker_contracts (
    tenant_id uuid NOT NULL,
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    entity_id bigint NOT NULL,
    name character varying,
    description text,
    reference_name character varying,
    nature character varying,
    contract_end character varying,
    started_at timestamp without time zone NOT NULL,
    stopped_at timestamp without time zone,
    salaried boolean DEFAULT false NOT NULL,
    monthly_duration numeric(8,2) NOT NULL,
    raw_hourly_amount numeric(8,2) NOT NULL,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    creator_id bigint,
    updater_id bigint,
    lock_version integer DEFAULT 0 NOT NULL,
    custom_fields jsonb,
    distribution_key character varying,
    CONSTRAINT worker_contracts_pkey PRIMARY KEY (tenant_id, id)
);

CREATE TABLE ekylibre.worker_group_items (
    tenant_id uuid NOT NULL,
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    worker_id uuid,
    worker_group_id bigint,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    CONSTRAINT worker_group_items_pkey PRIMARY KEY (tenant_id, id)
);

CREATE TABLE ekylibre.worker_group_labellings (
    tenant_id uuid NOT NULL,
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    worker_group_id bigint,
    label_id bigint,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    CONSTRAINT worker_group_labellings_pkey PRIMARY KEY (tenant_id, id)
);

CREATE TABLE ekylibre.worker_groups (
    tenant_id uuid NOT NULL,
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    name character varying NOT NULL,
    work_number character varying,
    active boolean DEFAULT true NOT NULL,
    usage character varying,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    creator_id bigint,
    updater_id bigint,
    lock_version integer DEFAULT 0 NOT NULL,
    CONSTRAINT worker_groups_pkey PRIMARY KEY (tenant_id, id)
);

CREATE TABLE ekylibre.worker_time_logs (
    tenant_id uuid NOT NULL,
    id uuid DEFAULT uuidv7() NOT NULL,
    worker_id uuid NOT NULL,
    started_at timestamp without time zone NOT NULL,
    stopped_at timestamp without time zone NOT NULL,
    duration integer NOT NULL,
    description text,
    custom_fields jsonb DEFAULT '{}'::jsonb,
    provider jsonb DEFAULT '{}'::jsonb,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    creator_id bigint,
    updater_id bigint,
    lock_version integer DEFAULT 0 NOT NULL,
    project_task_id bigint,
    travel_expense boolean DEFAULT false NOT NULL,
    travel_expense_details text,
    CONSTRAINT worker_time_logs_pkey PRIMARY KEY (tenant_id, id)
);

CREATE TABLE ekylibre.yield_observations (
    tenant_id uuid NOT NULL,
    id uuid DEFAULT uuidv7() NOT NULL,
    observed_at timestamp without time zone,
    activity_id bigint NOT NULL,
    vegetative_stage_id integer,
    geolocation postgis.geometry(Point,4326),
    description text,
    number character varying,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    creator_id bigint,
    updater_id bigint,
    lock_version integer DEFAULT 0 NOT NULL,
    provider jsonb DEFAULT '{}'::jsonb,
    CONSTRAINT yield_observations_pkey PRIMARY KEY (tenant_id, id)
);

